"""Record only verified outcomes from this audit checkpoint; no inferred passes."""
from pathlib import Path
import json,csv
from datetime import datetime,timezone

root=Path(__file__).resolve().parent
read=lambda path:json.loads((root/path).read_text(encoding='utf-8'))
results=read('results.json')
legacy=read('evidence/LEGACY-independent-verification.json')
assert [r['version'] for r in legacy['results']]==[1,2,9]
assert all(r['render_pixels_exact'] and r['current_save_reopen_exact'] for r in legacy['results'])
case=results['cases']['FILE-015']
case.update(variants_executed='Genuine v1/v2/v9 downloads produced by their untouched historical source revisions, actual current chooser migration, current project save and fresh-tab upgraded reopen; v2 exposure and committed crop; v9 STL. Unknown future versions 11/999 rejected.',criteria_observations='All original fields and embedded PNG pixels are retained. Historical/current/reopened compositions are pixel exact for all three versions. The v2 project preserves the 1024x256 original under its 768x192 crop and exposure recipe. The v9 cube exports byte-identical STL, independently verified as closed and oriented, 20mm on each axis and 8000mm³. User confirmed no older saved files are available for versions 3–8 on 2026-10-20.',independent_oracle='Pillow 12.3.0; exact parsed JSON and embedded RGBA; independent Python struct/math STL edge/normal/bounds/volume checks; Git source archive hashes',evidence_paths='legacy/producer-manifest.json; evidence/LEGACY-independent-verification.json; fixtures/legacy-v1-3916c24.retropaint; fixtures/legacy-v2-5ae1169.retropaint; fixtures/legacy-v9-c85f751.retropaint; evidence/FILE-016-independent-verification.json; ui-events-more.jsonl; ui-events-current.jsonl',defect_or_blocker='Versions 3–8 Blocked: no authentic fixture bytes or committed producers found, and user has no older files. Modern files were never relabelled. Earlier uncommitted v2 crop attempt is preserved under exposure-only evidence names.')
corrupt=read('evidence/FILE-016-independent-verification.json')
assert len(corrupt['results'])==20 and all(r['saved_document_exact'] for r in corrupt['results']) and corrupt['final_composition_exact']
case=results['cases']['FILE-016']
case.update(status='Pass',variants_executed=case['variants_executed']+' Additional real chooser inputs: photo value type, unordered red curve, unknown look, unsupported live kind/mode/brush, parallel CAD axes and left-handed CAD workplane. Each followed by a successful valid open.',criteria_observations='All twenty malformed/unsupported inputs are rejected with format-specific messages. Every rejection leaves an identical full saved project; no partial layer becomes active. A valid project opens after each failure and the final PNG equals the original exactly. Original D-005 acceptance failures are preserved.',evidence_paths=case['evidence_paths']+'; evidence/CORRUPT-live-reference.retropaint; ui-events-current.jsonl',defect_or_blocker='D-005 fixed. Twenty independent rejection snapshots and the final composition verified exactly; every listed corruption family executed.')
results['cases']['ACCESS-018']=dict(status='Partial',variants_executed='Actual 390x844 responsive frame target measurements before/after; native UI creation and exact 12.5mm position application; 59 supplementary full layout checks at 390x844, including all feature editor field reachability. 320x568 and 844x390 runs in progress.',criteria_observations='Original standard controls ranged from 15/22 to 40px and some actions shrank to 28.677px. Compact CAD now keeps natural scale and contained panel scrolling; the repaired 390x844 standard target measurement has no undersized targets, and stricter field/tab/header/layer-eye checks pass. Physical touch input remains unavailable. Browser viewport override did not change actual dimensions; frames were independently measured as 390x844. A frame STL click reported ready but produced no captured download; no downloaded-byte pass is claimed from it.',independent_oracle='Read-only DOM effective rectangles, checkbox label hit areas, visual screenshots, actual frame dimensions; native browser mouse/keyboard actions',evidence_paths='evidence/ACCESS-018-phone-brush-before.json; evidence/ACCESS-018-phone-CAD-before.json; evidence/ACCESS-018-phone-CAD-after.json; evidence/ACCESS-018-phone-position-applied.txt; evidence/ACCESS-018-phone-position-applied.png; evidence/regression-phone-390-before-reachability-assertions.txt; evidence/regression-phone-390-current.txt',defect_or_blocker='D-006 compact layout fix under verification. Other phone layouts and further actual workflows pending. Physical touch/pen unavailable; browser events are not physical-device certification.')
results['supplementary_checks']['browser_regressions'].update(count=228,evidence='evidence/regression-painting-current.json',scope='228 existing component/integration checks captured before the compact UI adjustment. These are not 349 acceptance passes. Final source rerun pending.')
results['supplementary_checks']['desktop_layout']=dict(status='Pass',count=57,evidence='evidence/regression-mobile-current.txt',scope='Full desktop sequence after drawer/fixture repairs, before compact CAD layout adjustment; latest rerun pending.')
results['supplementary_checks']['phone_390_layout']=dict(status='Pass',count=59,evidence='evidence/regression-phone-390-current.txt',scope='Actual 390x844 iframe. Real mouse input and synthetic regression events; no physical touch/pen or screen reader.')
results['updated_at']=datetime.now(timezone.utc).isoformat()
(root/'results.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
path=root.parents[1]/'VARIANT-EXECUTION-LEDGER.csv'
with path.open(encoding='utf-8-sig',newline='') as f:reader=csv.DictReader(f);fields=reader.fieldnames;rows=list(reader)
updates={'Image formats':('evidence/FILE-002-independent-comparison.json; evidence/EXPORT-independent-verification.json; evidence/FILE-009-011-independent-verification.json','All seven supported import formats and all six actual export codecs executed. Native chooser Cancel and remaining FILE-006 workflow still pending.'),'Document boundaries and storage':('evidence/FILE-016-independent-verification.json','Twenty atomic project rejections verified. Storage quota, layer/resource limits and other linked cases remain untested.'),'Workspace matrix':('evidence/regression-phone-390-current.txt; evidence/ACCESS-018-phone-CAD-after.json','390x844 full component sequence and actual target/workflow observations recorded. Other sizes, hardware input and assistive technology remain pending.')}
for row in rows:
    if row['family'] in updates:
        evidence,notes=updates[row['family']];row.update(status='Partial',run_id=results['run_id'],evidence_paths='runs/'+root.name+'/'+evidence.replace('; ','; runs/'+root.name+'/'),notes=row['notes']+' Executed: '+notes)
if not any(row['family']=='Project compatibility' for row in rows):rows.append(dict(family='Project compatibility',case_ids='FILE-015',variant_values=json.dumps(list(range(1,11))),status='Partial',run_id=results['run_id'],evidence_paths='runs/'+root.name+'/evidence/LEGACY-independent-verification.json',notes='Authentic versions 1,2,9 migrated and upgraded project reopened exactly. Current v10 save/reopen executed. Versions 3–8 Blocked: no producer/fixtures found; user confirms none available. Unknown future versions rejected.'))
with path.open('w',encoding='utf-8',newline='') as f:writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(rows)
print('Recorded verified recipe/migration results and partial responsive coverage; no new untested Pass entries')
